import{_ as e,o as n,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Transformer 与 Attention","description":"沿序列数据流理解位置表示、Q/K/V、因果掩码、多头注意力、前馈层、残差、归一化与层叠结构。","frontmatter":{"title":"Transformer 与 Attention","description":"沿序列数据流理解位置表示、Q/K/V、因果掩码、多头注意力、前馈层、残差、归一化与层叠结构。","verified_at":"2026-07-28","sources":["https://arxiv.org/abs/1706.03762","https://arxiv.org/abs/2005.14165","https://web.stanford.edu/~jurafsky/slp3/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/transformer-attention.md","filePath":"py-agent/foundations/model-principles/transformer-attention.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/transformer-attention.md"};function r(l,a,o,p,d,h){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="transformer-与-attention" tabindex="-1">Transformer 与 Attention <a class="header-anchor" href="#transformer-与-attention" aria-label="Permalink to &quot;Transformer 与 Attention&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Embedding 给每个 Token 位置一个初始向量，Transformer 则反复更新这些向量，使每个位置结合当前上下文形成新的表示。Attention 负责在位置之间传递信息，前馈网络负责对每个位置做非线性变换，残差和归一化让深层网络更容易训练。</p><p>本章以现代自回归生成模型常见的 decoder-only Transformer 为主。不同模型会调整归一化、位置编码、Attention 和前馈层细节，但主数据流相近。</p><h2 id="_1-transformer-处理的对象" tabindex="-1">1. Transformer 处理的对象 <a class="header-anchor" href="#_1-transformer-处理的对象" aria-label="Permalink to &quot;1. Transformer 处理的对象&quot;">​</a></h2><h3 id="_1-1-输入是一列位置向量" tabindex="-1">1.1 输入是一列位置向量 <a class="header-anchor" href="#_1-1-输入是一列位置向量" aria-label="Permalink to &quot;1.1 输入是一列位置向量&quot;">​</a></h3><p>文本经过分词和 Embedding 后形成长度为 <code>L</code>、隐藏维度为 <code>D</code> 的序列：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Token:     [t₁, t₂, t₃, ..., tL]</span></span>
<span class="line"><span>表示:      [h₁, h₂, h₃, ..., hL]</span></span>
<span class="line"><span>每个 hᵢ 是 D 维向量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Transformer 层输入和输出通常保持 <code>L × D</code> 的整体形状，但每个 <code>hᵢ</code> 的内容不断被更新。</p><h3 id="_1-2-模型必须知道位置" tabindex="-1">1.2 模型必须知道位置 <a class="header-anchor" href="#_1-2-模型必须知道位置" aria-label="Permalink to &quot;1.2 模型必须知道位置&quot;">​</a></h3><p>Attention 只看向量关系时无法天然区分排列顺序，所以模型会加入或使用位置编码。位置机制让“谁在前、距离多远”进入计算。</p><h3 id="_1-3-每个位置承担双重职责" tabindex="-1">1.3 每个位置承担双重职责 <a class="header-anchor" href="#_1-3-每个位置承担双重职责" aria-label="Permalink to &quot;1.3 每个位置承担双重职责&quot;">​</a></h3><p>一个位置既表示自己的 Token，又携带从允许关注的其他位置汇集来的上下文信息。多层之后，最后一个输入位置的隐藏状态可以概括当前生成所需的上下文，并用于预测下一个 Token。</p><h2 id="_2-self-attention-的问题" tabindex="-1">2. Self-Attention 的问题 <a class="header-anchor" href="#_2-self-attention-的问题" aria-label="Permalink to &quot;2. Self-Attention 的问题&quot;">​</a></h2><p>Self-Attention 要回答：对当前位置而言，序列中哪些已允许位置与当前计算相关，应从它们取回多少信息？</p><p>例如处理“动物没有过马路，因为<strong>它</strong>太累了”中的“它”时，当前表示可能需要结合“动物”而不是“马路”。这种关系不是预先写死的语法规则，而是由训练得到的投影和当前输入共同决定。</p><h2 id="_3-query、key-与-value" tabindex="-1">3. Query、Key 与 Value <a class="header-anchor" href="#_3-query、key-与-value" aria-label="Permalink to &quot;3. Query、Key 与 Value&quot;">​</a></h2><h3 id="_3-1-同一表示投影成三种角色" tabindex="-1">3.1 同一表示投影成三种角色 <a class="header-anchor" href="#_3-1-同一表示投影成三种角色" aria-label="Permalink to &quot;3.1 同一表示投影成三种角色&quot;">​</a></h3><p>每个位置的输入向量分别经过学习到的矩阵，得到：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q = H · WQ</span></span>
<span class="line"><span>K = H · WK</span></span>
<span class="line"><span>V = H · WV</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>Query 表示当前位置正在寻找什么信息。</li><li>Key 表示每个候选位置可按什么特征被匹配。</li><li>Value 表示匹配后实际汇入的信息。</li></ul><p>这是帮助理解的职责划分，不意味着 Q/K/V 的每个维度都有人类可读含义。</p><h3 id="_3-2-相似分数决定关注强度" tabindex="-1">3.2 相似分数决定关注强度 <a class="header-anchor" href="#_3-2-相似分数决定关注强度" aria-label="Permalink to &quot;3.2 相似分数决定关注强度&quot;">​</a></h3><p>一个 Query 与所有允许 Key 做点积，得到匹配分数。常见的缩放点积注意力为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Attention(Q, K, V)</span></span>
<span class="line"><span>= softmax((Q · Kᵀ) / sqrt(dk) + mask) · V</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>sqrt(dk)</code> 缩放避免维度增大时点积过大；<code>softmax</code> 把分数转换为和为 1 的权重；权重再对 Value 做加权求和。</p><h3 id="_3-3-权重是当前层当前头的路由" tabindex="-1">3.3 权重是当前层当前头的路由 <a class="header-anchor" href="#_3-3-权重是当前层当前头的路由" aria-label="Permalink to &quot;3.3 权重是当前层当前头的路由&quot;">​</a></h3><p>注意力权重说明一次局部计算怎样混合 Value。它不是模型全部推理过程，也不天然等同于人类解释或因果贡献。后续层、前馈网络和残差路径都会继续改变表示。</p><h2 id="_4-因果掩码" tabindex="-1">4. 因果掩码 <a class="header-anchor" href="#_4-因果掩码" aria-label="Permalink to &quot;4. 因果掩码&quot;">​</a></h2><h3 id="_4-1-生成模型不能偷看未来-token" tabindex="-1">4.1 生成模型不能偷看未来 Token <a class="header-anchor" href="#_4-1-生成模型不能偷看未来-token" aria-label="Permalink to &quot;4.1 生成模型不能偷看未来 Token&quot;">​</a></h3><p>训练下一个 Token 预测时，位置 <code>i</code> 只能使用位置 <code>1...i</code>，不能看到真实的 <code>i+1</code> 以后内容。因果掩码把未来位置的注意力分数设为不可选择。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        可关注的 Key 位置</span></span>
<span class="line"><span>Query   1  2  3  4</span></span>
<span class="line"><span>  1     ✓  ×  ×  ×</span></span>
<span class="line"><span>  2     ✓  ✓  ×  ×</span></span>
<span class="line"><span>  3     ✓  ✓  ✓  ×</span></span>
<span class="line"><span>  4     ✓  ✓  ✓  ✓</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_4-2-掩码建立自回归信息边界" tabindex="-1">4.2 掩码建立自回归信息边界 <a class="header-anchor" href="#_4-2-掩码建立自回归信息边界" aria-label="Permalink to &quot;4.2 掩码建立自回归信息边界&quot;">​</a></h3><p>因为位置不能依赖未来，训练时每个位置都能同时预测自己的下一个 Token；生成时却仍要先得到前一个 Token，才能构造下一位置。因此 Transformer 可以并行处理已知输入，却不能一次确定所有未知输出。</p><h3 id="_4-3-填充掩码与因果掩码不同" tabindex="-1">4.3 填充掩码与因果掩码不同 <a class="header-anchor" href="#_4-3-填充掩码与因果掩码不同" aria-label="Permalink to &quot;4.3 填充掩码与因果掩码不同&quot;">​</a></h3><p>批处理可能补齐不同长度序列，填充掩码用于忽略无效填充位置；因果掩码用于阻止看见未来。二者可能一起使用，但解决的问题不同。</p><h2 id="_5-多头注意力" tabindex="-1">5. 多头注意力 <a class="header-anchor" href="#_5-多头注意力" aria-label="Permalink to &quot;5. 多头注意力&quot;">​</a></h2><h3 id="_5-1-多个头使用不同投影" tabindex="-1">5.1 多个头使用不同投影 <a class="header-anchor" href="#_5-1-多个头使用不同投影" aria-label="Permalink to &quot;5.1 多个头使用不同投影&quot;">​</a></h3><p>单个注意力头只有一套 Q/K/V 投影。多头注意力让多个子空间并行计算，再拼接并投影回隐藏维度：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 H</span></span>
<span class="line"><span>  -&gt; head₁(Q₁, K₁, V₁)</span></span>
<span class="line"><span>  -&gt; head₂(Q₂, K₂, V₂)</span></span>
<span class="line"><span>  -&gt; ...</span></span>
<span class="line"><span>  -&gt; 拼接</span></span>
<span class="line"><span>  -&gt; 输出投影</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>不同头可以学习不同关系，例如局部搭配、远距离引用或结构边界，但不能假设每个头固定对应一个清晰语言规则。</p><h3 id="_5-2-头数不是独立专家数量" tabindex="-1">5.2 头数不是独立专家数量 <a class="header-anchor" href="#_5-2-头数不是独立专家数量" aria-label="Permalink to &quot;5.2 头数不是独立专家数量&quot;">​</a></h3><p>注意力头共同构成一层计算，信息还会通过输出投影、残差和后续层混合。模型是否使用专家混合架构是另一件事，不能与多头注意力混为一谈。</p><h2 id="_6-前馈网络" tabindex="-1">6. 前馈网络 <a class="header-anchor" href="#_6-前馈网络" aria-label="Permalink to &quot;6. 前馈网络&quot;">​</a></h2><h3 id="_6-1-attention-在位置间混合信息" tabindex="-1">6.1 Attention 在位置间混合信息 <a class="header-anchor" href="#_6-1-attention-在位置间混合信息" aria-label="Permalink to &quot;6.1 Attention 在位置间混合信息&quot;">​</a></h3><p>Attention 的主要作用是让每个位置从其他位置汇集 Value。得到的仍是每个位置一个向量。</p><h3 id="_6-2-前馈层逐位置变换" tabindex="-1">6.2 前馈层逐位置变换 <a class="header-anchor" href="#_6-2-前馈层逐位置变换" aria-label="Permalink to &quot;6.2 前馈层逐位置变换&quot;">​</a></h3><p>前馈网络对每个位置应用相同参数的非线性变换，常见结构先扩展维度、应用激活或门控，再投影回隐藏维度。不同位置独立执行，但因为输入已经包含上下文，变换结果仍是上下文化的。</p><p>可以把二者粗略区分为：Attention 决定“从哪里取信息”，前馈层决定“怎样变换当前位置的信息”。真实模型的功能分工比这个比喻更分布式。</p><h2 id="_7-残差连接与归一化" tabindex="-1">7. 残差连接与归一化 <a class="header-anchor" href="#_7-残差连接与归一化" aria-label="Permalink to &quot;7. 残差连接与归一化&quot;">​</a></h2><h3 id="_7-1-残差保留原路径" tabindex="-1">7.1 残差保留原路径 <a class="header-anchor" href="#_7-1-残差保留原路径" aria-label="Permalink to &quot;7.1 残差保留原路径&quot;">​</a></h3><p>子层输出通常与输入相加：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>output = input + sublayer(input)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这让子层学习对现有表示的修正，并为深层网络提供直接的信息和梯度路径。</p><h3 id="_7-2-归一化稳定数值尺度" tabindex="-1">7.2 归一化稳定数值尺度 <a class="header-anchor" href="#_7-2-归一化稳定数值尺度" aria-label="Permalink to &quot;7.2 归一化稳定数值尺度&quot;">​</a></h3><p>Layer Normalization 或 RMSNorm 等机制控制每个位置表示的数值尺度。不同架构可能在子层之前或之后归一化，不能把一种顺序当作所有 Transformer 的固定定义。</p><h3 id="_7-3-一层包含多个共同工作的组件" tabindex="-1">7.3 一层包含多个共同工作的组件 <a class="header-anchor" href="#_7-3-一层包含多个共同工作的组件" aria-label="Permalink to &quot;7.3 一层包含多个共同工作的组件&quot;">​</a></h3><p>典型层可以概括为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入</span></span>
<span class="line"><span>  -&gt; 归一化 -&gt; 多头因果 Self-Attention -&gt; 残差相加</span></span>
<span class="line"><span>  -&gt; 归一化 -&gt; 前馈网络              -&gt; 残差相加</span></span>
<span class="line"><span>  -&gt; 下一层</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>具体模型可能使用并行残差、门控前馈、分组查询注意力等变化，但都应沿实际架构说明，不能只凭“Transformer”名称推断所有细节。</p><h2 id="_8-层叠后的数据流" tabindex="-1">8. 层叠后的数据流 <a class="header-anchor" href="#_8-层叠后的数据流" aria-label="Permalink to &quot;8. 层叠后的数据流&quot;">​</a></h2><h3 id="_8-1-浅层到深层不是固定语义阶梯" tabindex="-1">8.1 浅层到深层不是固定语义阶梯 <a class="header-anchor" href="#_8-1-浅层到深层不是固定语义阶梯" aria-label="Permalink to &quot;8.1 浅层到深层不是固定语义阶梯&quot;">​</a></h3><p>多层反复进行上下文路由和逐位置变换，表示逐渐适合最终预测。研究常观察到不同层对词法、句法或语义信息的敏感度不同，但不存在适用于所有模型的严格“第一层识字、最后一层推理”分工表。</p><h3 id="_8-2-输出投影产生词表分数" tabindex="-1">8.2 输出投影产生词表分数 <a class="header-anchor" href="#_8-2-输出投影产生词表分数" aria-label="Permalink to &quot;8.2 输出投影产生词表分数&quot;">​</a></h3><p>最后一层目标位置的隐藏状态经过输出投影，得到词表中每个 Token 的 logits。softmax 再把 logits 转换为概率分布，供解码策略选择下一个 Token。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Token ID</span></span>
<span class="line"><span>  -&gt; Embedding + 位置机制</span></span>
<span class="line"><span>  -&gt; N 个 Transformer 层</span></span>
<span class="line"><span>  -&gt; 最后位置隐藏状态</span></span>
<span class="line"><span>  -&gt; 词表 logits</span></span>
<span class="line"><span>  -&gt; 下一个 Token 分布</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_8-3-生成会重复这条路径" tabindex="-1">8.3 生成会重复这条路径 <a class="header-anchor" href="#_8-3-生成会重复这条路径" aria-label="Permalink to &quot;8.3 生成会重复这条路径&quot;">​</a></h3><p>选出一个新 Token 后，模型为扩展后的序列继续计算。推理系统会缓存历史位置的 Key 和 Value，避免每一步重复计算全部历史内容；这就是后续“推理与采样”中的 KV cache。</p><h2 id="_9-attention-的计算边界" tabindex="-1">9. Attention 的计算边界 <a class="header-anchor" href="#_9-attention-的计算边界" aria-label="Permalink to &quot;9. Attention 的计算边界&quot;">​</a></h2><h3 id="_9-1-标准全注意力随长度快速增长" tabindex="-1">9.1 标准全注意力随长度快速增长 <a class="header-anchor" href="#_9-1-标准全注意力随长度快速增长" aria-label="Permalink to &quot;9.1 标准全注意力随长度快速增长&quot;">​</a></h3><p>长度为 <code>L</code> 的序列形成约 <code>L × L</code> 的位置匹配矩阵，因此计算和内存压力随上下文增长很快。现代模型会使用更高效内核、稀疏模式或其他优化，但长上下文仍有显著资源成本。</p><h3 id="_9-2-能关注不等于能可靠使用" tabindex="-1">9.2 能关注不等于能可靠使用 <a class="header-anchor" href="#_9-2-能关注不等于能可靠使用" aria-label="Permalink to &quot;9.2 能关注不等于能可靠使用&quot;">​</a></h3><p>一个位置在掩码上可见，只表示计算允许建立联系。模型是否学会找到关键证据、解决冲突并保持长距离一致性，仍取决于训练和任务分布。</p><h3 id="_9-3-attention-不是外部记忆" tabindex="-1">9.3 Attention 不是外部记忆 <a class="header-anchor" href="#_9-3-attention-不是外部记忆" aria-label="Permalink to &quot;9.3 Attention 不是外部记忆&quot;">​</a></h3><p>Attention 只能读取当前上下文和当前层表示。参数更新、长期记忆、数据库检索和工具调用都是不同机制。</p><h2 id="_10-常见误解" tabindex="-1">10. 常见误解 <a class="header-anchor" href="#_10-常见误解" aria-label="Permalink to &quot;10. 常见误解&quot;">​</a></h2><h3 id="_10-1-attention-权重就是答案依据" tabindex="-1">10.1 “Attention 权重就是答案依据” <a class="header-anchor" href="#_10-1-attention-权重就是答案依据" aria-label="Permalink to &quot;10.1 “Attention 权重就是答案依据”&quot;">​</a></h3><p>权重只是某层某头的中间路由信号。可靠解释还需干预实验、输出验证和外部证据。</p><h3 id="_10-2-transformer-并行-所以输出也一次生成" tabindex="-1">10.2 “Transformer 并行，所以输出也一次生成” <a class="header-anchor" href="#_10-2-transformer-并行-所以输出也一次生成" aria-label="Permalink to &quot;10.2 “Transformer 并行，所以输出也一次生成”&quot;">​</a></h3><p>已知输入可并行编码；未知输出存在自回归依赖，通常仍逐 Token 产生。</p><h3 id="_10-3-上下文越长-模型记得越完整" tabindex="-1">10.3 “上下文越长，模型记得越完整” <a class="header-anchor" href="#_10-3-上下文越长-模型记得越完整" aria-label="Permalink to &quot;10.3 “上下文越长，模型记得越完整”&quot;">​</a></h3><p>窗口容量、注意力可达和任务利用质量是三件事。长输入需要专门评测。</p><h2 id="_11-自测" tabindex="-1">11. 自测 <a class="header-anchor" href="#_11-自测" aria-label="Permalink to &quot;11. 自测&quot;">​</a></h2><ol><li>Q、K、V 在一次 Attention 计算中分别承担什么角色？</li><li>因果掩码为什么允许并行训练，却仍要求逐 Token 生成？</li><li>多头注意力与专家混合有什么概念差异？</li><li>Attention 和前馈网络对位置表示的作用有何不同？</li><li>残差、归一化和层叠结构为什么不能从模型说明中省略？</li></ol><p>能够沿“位置表示 → Q/K/V → 因果加权 → 多头合并 → 前馈变换 → 残差与归一化 → 词表 logits”解释数据流，就理解了 Transformer 的核心计算骨架。</p>`,85)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
